// book: pre-sized open-addressing map from interned symbol id -> price
void onQuote(const Quote& q, FlatBook& book, LogRing& log) noexcept {
    book.set(q.sym_id, q.price);                 // O(1), no alloc, no tree
    log.push(LogRec{LogRec::QUOTE, q.sym_id});   // off-path: bg thread formats/writes
}
// No shared_ptr, no string copy, no std::map, no std::function, no inline I/O.
